const email = $input.first().json;
let sender = '';
if (typeof email.from === 'string') sender = email.from;
else if (email.from?.text) sender = email.from.text;
else if (email.from?.value?.[0]?.address) sender = email.from.value[0].address;
else if (email.headers?.from) sender = email.headers.from;
sender = String(sender || '');
const match = sender.match(/<([^>]+)>/);
const senderEmail = match ? match[1].trim() : (sender.trim() || 'customer@example.com');
return [{ json: { sender_email: senderEmail, subject: String(email.subject || email.headers?.subject || 'Support Query'), customer_query: String(email.snippet || email.textPlain || email.text || email.subject || '').trim(), message_id: email.id || email.messageId || '' } }];

const matches = $json.matches || [];
const topScore = matches.length > 0 ? matches[0].score : 0;
const context = matches.map(m => (m.metadata ? m.metadata.text : '')).filter(Boolean).join('\n\n');
const original = $('Parse Inbound Email').first().json;
const query = (original.customer_query || '').toLowerCase();
const isHighRisk = query.includes('fraud hold') || query.includes('unfreeze') || query.includes('dispute') || query.includes('chargeback') || query.includes('reversal');
const isConfident = topScore >= 0.70 && context.trim().length > 0;
return [{ json: { sender_email: original.sender_email, subject: original.subject, customer_query: original.customer_query, retrieved_context: isConfident ? context : 'INSUFFICIENT_INFORMATION', top_score: topScore, requires_human_approval: isHighRisk || !isConfident, high_risk: isHighRisk } }];

const original = $('Evaluate Guardrail').first().json;
const draft = $('Gemini Draft Reply').first().json.candidates[0].content.parts[0].text || '';
let hallucinated = false;
let reason = '';
try {
  const raw = $json.candidates[0].content.parts[0].text || '';
  let cleaned = raw.replace(/```json|```/g, '').trim();
  const firstBrace = cleaned.indexOf('{');
  const lastBrace = cleaned.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) cleaned = cleaned.slice(firstBrace, lastBrace + 1);
  const parsed = JSON.parse(cleaned);
  hallucinated = !!parsed.hallucinated;
  reason = String(parsed.reason || '');
} catch (e) {
  hallucinated = true;
  reason = 'hallucination_check_unparseable';
}
return [{ json: { sender_email: original.sender_email, subject: original.subject, customer_query: original.customer_query, retrieved_context: original.retrieved_context, top_score: original.top_score, draft_response: draft, hallucinated, hallucination_reason: reason, requires_human_approval: original.requires_human_approval || hallucinated } }];

