if (typeof payload === 'string') { try { payload = JSON.parse(payload); } catch (e) {} }
const row = Array.isArray(payload) ? payload[0] : payload;
const approvalId = row?.approval_id || row?.[0]?.approval_id || (typeof row === 'object' && row !== null ? Object.values(row)[0] : null);
if (!approvalId || typeof approvalId !== 'string') throw new Error('create_approval_request did not return approval_id. Got: ' + JSON.stringify($json));
return [{ json: { approval_id: approvalId } }];

