const approvalId = $('Extract Approval ID').item.json.approval_id;
const approveRaw = $('Sign Approve Token').item.json;
const rejectRaw  = $('Sign Reject Token').item.json;
function extractToken(obj) {
  if (obj == null) return '';
  if (typeof obj === 'string') return obj;
  if (typeof obj.data === 'string') return obj.data;
  if (typeof obj.sign_approval_token === 'string') return obj.sign_approval_token;
  if (typeof obj === 'object') { const values = Object.values(obj); if (values.length && typeof values[0] === 'string') return values[0]; }
  return '';
}
let approveStr = extractToken(approveRaw).replace(/^"|"$/g, '').trim();
let rejectStr  = extractToken(rejectRaw).replace(/^"|"$/g, '').trim();
if (!approveStr || !rejectStr) throw new Error('Missing signed token.');
const original = $('Merge Hallucination Result').first().json;
const base = ($vars.N8N_PUBLIC_URL || '').replace(/\/$/, '');
if (!base) throw new Error('N8N_PUBLIC_URL variable not set');
return [{ json: { approval_id: approvalId, approve_url: base + '/webhook/rag-approve?token=' + encodeURIComponent(approveStr), reject_url: base + '/webhook/rag-approve?token=' + encodeURIComponent(rejectStr), sender_email: original.sender_email, subject: original.subject, customer_query: original.customer_query, draft_response: original.draft_response, hallucinated: original.hallucinated, hallucination_reason: original.hallucination_reason } }];

